function oddThenEven(head: ListNode | null): ListNode | null {
  const odds: ListNode[] = [], evens: ListNode[] = [];
  for (let n = head, i = 1; n; n = n.next, i++) (i % 2 ? odds : evens).push(n);
  const all = [...odds, ...evens];
  for (let i = 0; i < all.length; i++) all[i].next = all[i + 1] ?? null;
  return all.length ? all[0] : null;
}

