class Solution:
    def oddThenEven(self, head: Optional[ListNode]) -> Optional[ListNode]:
        nodes = []
        while head:
            nodes.append(head)
            head = head.next
        order = nodes[0::2] + nodes[1::2]
        for a, b in zip(order, order[1:]):
            a.next = b
        if order:
            order[-1].next = None
        return order[0] if order else None

