function oddThenEven(head: ListNode | null): ListNode | null {
  if (!head || !head.next) return head;
  let odd = head, even: ListNode | null = head.next;
  const evenHead = even;
  while (even && even.next) {
    odd.next = even.next;
    odd = odd.next;
    even.next = odd.next;
    even = even.next;
  }
  odd.next = evenHead;
  return head;
}

